class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    # For __hash__ to work, objects must be immutable or treated as such.
    # For simplicity, we assume x and y are not modified after creation.

    def __eq__(self, other):
        if not isinstance(other, Point):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def __hash__(self):
        # Tuple hashing is commonly used for immutable objects
        return hash((self.x, self.y))

    def __repr__(self):
        return f"Point({self.x}, {self.y})"

# Example usage:
p1 = Point(1, 2)
p2 = Point(1, 2)
p3 = Point(3, 4)

my_dict = {p1: "first point"}
print(my_dict[p2]) # Output: first point (because p1 == p2 and hash(p1) == hash(p2))
```
